def Def5 (𝓢 : S) (D K : Fm → Fm) : Prop := ∀ φ, 𝓢 ⊢ φ → 𝓢 ⊢ D φ → 𝓢 ⊢ K φ

def Def6 (𝓢 : S) (D T : Fm → Fm) : Prop := ∀ φ, 𝓢 ⊢ D φ 🡒 (T φ 🡘 φ)

def Def7 (𝓢 : S) (D T : Fm → Fm) : Prop := ∀ φ ψ, 𝓢 ⊢ D (φ 🡒 ψ) 🡘 (D φ ⋏ (T φ 🡒 D ψ))

def Def8 (𝓢 : S) (D K : Fm → Fm) : Prop := ∀ φ, 𝓢 ⊢ D (K φ) 🡘 D φ

